installer-gui-script.script:

// An install over an earlier one keeps its sign-in item: the choice starts on when the LaunchAgent is there.
function loginItemOn() {
    var agent = "/Library/LaunchAgents/io.github.tannermidd.pi-pocket.plist";

    try {
        return system.files.fileExistsAtPath(system.env.HOME + agent);
    } catch (error) {
        return false;
    }
}
